using System.Text.Json;
using Arcoll.WinUI3.Services.PenteFino;
int checks=0;void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
void Refused(Action fn,string label){try{fn();throw new Exception("Accepted invalid input: "+label);}catch(InvalidDataException){checks++;}}
Finding F(string id,string module,bool fix=true,string severity="info",long bytes=10)=>new(id,module,"Name-"+id,"C:\\private\\customer\\"+id,bytes,"diagnostic","action",fix,fix?"file":"info",Severity:severity);
var report=new ScanReport("pentefino.scan.v1","report-one",DateTimeOffset.UtcNow,"detailed",[new("clean","Limpeza",[F("one","clean"),F("one","clean"),F("two","clean"),F("info","clean",false)],[],true),new("startup","Inicialização",[F("manual","startup",false,"review"),F("three","startup")],["Restricted area"],false)],false,3);
var summary=Presentation.Summarize(report);Check(summary.Count==5,"summary deduplicates findings");Check(summary.Fixable==3&&summary.Review==1&&summary.Informational==1,"classifications remain separate");Check(!summary.Complete,"partial coverage is never displayed as fully checked");Check(summary.Bytes==50,"bytes counted once");Check(summary.Modules.Length==2,"one row per analyzed module");var wire=JsonSerializer.Serialize(summary);Check(!wire.Contains("customer")&&!wire.Contains("Name-one")&&!wire.Contains("Path"),"summary never contains file paths or complete item list");Check(Presentation.CorrectionIds(report,report.Id,new[]{"clean"}).SequenceEqual(new[]{"one","two"}),"category selection expands only eligible IDs");Refused(()=>Presentation.CorrectionIds(report,"stale",new[]{"clean"}),"stale report");Refused(()=>Presentation.CorrectionIds(report,report.Id,new[]{"clean","clean"}),"duplicate category");Refused(()=>Presentation.CorrectionIds(report,report.Id,new[]{"foreign"}),"unknown category");Refused(()=>Presentation.CorrectionIds(report with{Cancelled=true},report.Id,new[]{"clean"}),"interrupted report");
var large=report with{Modules=[new("clean","Limpeza",Enumerable.Range(0,20000).Select(i=>F("item-"+i,"clean")).ToList(),[],true)]};var largeJson=JsonSerializer.Serialize(Presentation.Summarize(large));Check(largeJson.Length<1500,"20k findings have bounded presentation payload");Check(Presentation.CorrectionIds(large,large.Id,new[]{"clean"}).Length==20000,"selection supports documented bound");var over=large with{Modules=[new("clean","Limpeza",Enumerable.Range(0,20001).Select(i=>F("over-"+i,"clean")).ToList(),[],true)]};Check(Presentation.CorrectionIds(over,over.Id,new[]{"clean"}).Length==20001,"selection above 20k is not artificially blocked");
var screenshotReport=report with{Modules=[new("clean","Limpeza",Enumerable.Range(0,20000).Select(i=>F("clean-"+i,"clean")).ToList(),[],true),new("privacy","Privacidade",Enumerable.Range(0,415).Select(i=>F("privacy-"+i,"privacy")).ToList(),[],true),new("startup","Inicialização",Enumerable.Range(0,2).Select(i=>F("startup-"+i,"startup")).ToList(),[],true),new("registry","Registro",Enumerable.Range(0,38).Select(i=>F("registry-"+i,"registry")).ToList(),[],true)]};
var screenshotSelection=Presentation.CorrectionIds(screenshotReport,screenshotReport.Id,new[]{"clean","privacy","startup","registry"});Check(screenshotSelection.Length==20455,"all 20455 screenshot adjustments expand across categories");
var temp=Path.Combine(Path.GetTempPath(),"pentefino-validation-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);
try{
 var source=Path.Combine(temp,"eligible");Directory.CreateDirectory(source);var file=Path.Combine(source,"test.tmp");File.WriteAllText(file,"controlled fixture content");File.SetLastWriteTimeUtc(file,DateTime.UtcNow.AddDays(-10));var info=new FileInfo(file);var store=new ResultsStore(Path.Combine(temp,"state"));store.SaveSettings(Settings.Default with{Mode="detailed",Modules=["clean"]});var policy=new PathPolicy([new("test-rule","clean",source,1)],[]);var item=new Finding("fixture-file","clean","Fixture",file,info.Length,"fixture","quarantine",true,"file","test-rule",ModifiedTicks:info.LastWriteTimeUtc.Ticks);var fixture=report with{Modules=[new("clean","Limpeza",[item],[],true)]};store.Save(fixture);store.Audit("test-start",new{fixture.Id});var engine=new FixEngine(store,policy);var progress=new CaptureProgress();var fixedReport=await engine.FixAsync(fixture,[item.Id],default,progress);Check(fixedReport.Results.Single().Ok&&!File.Exists(file),"eligible temporary fixture permanently removed");Check(!store.UndoEntries().Any(),"new corrections do not journal recovery copies");Check(!Directory.Exists(store.LocalPath("backup")),"new corrections do not create backup directory");Check(progress.Values.Last().Succeeded==1&&progress.Values.Last().Failed==0,"actual successful progress counters");Check(progress.Values.All(x=>x.Outcomes.Count==0),"progress remains bounded");var undone=await engine.UndoAsync(fixedReport.Session,default);Check(undone.Count==0&&!File.Exists(file),"new session has no recoverable copy");Check(store.VerifyAudit(),"audit verifies without storing original content");File.WriteAllText(file,"controlled fixture content");

 var cancelledLarge=await engine.FixAsync(screenshotReport,screenshotSelection,new CancellationToken(true));Check(cancelledLarge.Cancelled&&cancelledLarge.Results.Count==0,"engine accepts the whole 20455 selection before safe cancellation");
 // A cancelled operation cannot mutate a selected file or claim successful completion.
 var cancelled=await engine.FixAsync(fixture,[item.Id],new CancellationToken(true));Check(cancelled.Cancelled&&cancelled.Results.Count==0&&File.Exists(file),"cancellation preserves source");
 // Overlapping rules may return duplicate findings: orchestration publishes only one ID.
 var scan=await new ScanOrchestrator(store,[new FixtureChecker(item)]).ScanAsync(new("detailed",["clean"],[],[]),policy,null,default);Check(scan.Modules.Single().Items.Count==1,"orchestrator deduplicates overlapping checker results");
 // A changed file produces a failure, never a false 'fixed' count or deletion.
 var freshInfo=new FileInfo(file);var changed=item with{ModifiedTicks=freshInfo.LastWriteTimeUtc.Ticks,Bytes=freshInfo.Length};File.AppendAllText(file," changed after analysis");var failedProgress=new CaptureProgress();var failed=await engine.FixAsync(fixture with{Modules=[new("clean","Limpeza",[changed],[],true)]},[item.Id],default,failedProgress);Check(!failed.Results.Single().Ok&&File.Exists(file),"changed file preserved");Check(failedProgress.Values.Last().Failed==1&&failedProgress.Values.Last().Succeeded==0,"failure counted separately");
}finally{Directory.Delete(temp,true);}
Console.WriteLine($"PASS {checks} Pente-Fino summary, selection, no-copy corrections and progress assertions.");
sealed class CaptureProgress:IProgress<FixProgressState>{public List<FixProgressState> Values=[];public void Report(FixProgressState state)=>Values.Add(state);}
sealed class FixtureChecker(Finding item):IChecker{public string Id=>"clean";public string Title=>"Limpeza";public Task<CheckResult> ScanAsync(ScanContext context,CancellationToken ct)=>Task.FromResult(new CheckResult(Id,Title,[item,item],[],true));}
